private void btnComputePowerBillActionPerformed(java.awt.event.ActionEvent evt) {
    try {
        // Step 1: Read and validate numeric input
        String inputStr = txtAmount.getText().trim();
        if (inputStr.isEmpty()) {
            javax.swing.JOptionPane.showMessageDialog(this,
                "Input field cannot be empty!", "Validation Warning",
                javax.swing.JOptionPane.WARNING_MESSAGE);
            return;
        }

        double baseValue = Double.parseDouble(inputStr);
        if (baseValue < 0) {
            javax.swing.JOptionPane.showMessageDialog(this,
                "Value must be a positive number!", "Input Error",
                javax.swing.JOptionPane.ERROR_MESSAGE);
            return;
        }

        // Step 2: Tariff / Discount adjustment from Radio Buttons
        double adjustmentRate = 0.05; // 5% Standard
        if (rbPremium.isSelected()) {
            adjustmentRate = 0.15; // 15% Premium Service
        }

        double adjustedAmount = baseValue * (1.0 - adjustmentRate);

        // Step 3: Check optional add-on checkbox
        double addonCost = 0.0;
        if (chkAddon.isSelected()) {
            addonCost = 250.0; // Priority add-on
        }

        // Step 4: Final calculation
        double netTotal = adjustedAmount + addonCost;

        // Step 5: Format and display result
        txtFinalAmount.setText(String.format("₹ %.2f", netTotal));

    } catch (NumberFormatException ex) {
        javax.swing.JOptionPane.showMessageDialog(this,
            "Invalid numeric input! Please enter digits only.",
            "Parsing Error", javax.swing.JOptionPane.ERROR_MESSAGE);
    }
}
```

