public class BinarySearchBenchmark {
    public static void main(String[] args) {
        int[] dataset = {120, 240, 380, 420, 560, 680, 750, 920};
        int targetKey = 420;

        int low = 0;
        int high = dataset.length - 1;
        int foundIndex = -1;

        // Binary Search Divide-and-Conquer Loop
        while (low <= high) {
            int mid = low + (high - low) / 2;

            if (dataset[mid] == targetKey) {
                foundIndex = mid;
                break;
            } else if (dataset[mid] < targetKey) {
                low = mid + 1; // Search right half
            } else {
                high = mid - 1; // Search left half
            }
        }

        // Output reporting
        if (foundIndex != -1) {
            System.out.println("Target Key " + targetKey + " found successfully!");
            System.out.println("0-based Index: " + foundIndex);
            System.out.println("1-based Position: " + (foundIndex + 1));
        } else {
            System.out.println("Target Key " + targetKey + " not found in array.");
        }
    }
}
```

